using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Text;
using UnityEditor;
using UnityEngine;
using Yato.Resources;
using Yato.UI;

namespace Yato.Editor
{
    /// <summary>
    /// 扫描预制体生成 <c>AssetKeys.g.cs</c> 与 <c>UIPages.g.cs</c>（T-P4-03）。
    /// 约束：只读命名与目录、不读场景；生成物带 auto-generated 头；内容无变化不写盘。
    /// </summary>
    public static class AssetKeyGenerator
    {
        private const string AutoGeneratedHeader =
            "// <auto-generated>\n" +
            "//     此文件由 Yato.Editor/AssetKeyGenerator 生成，请勿手动修改。\n" +
            "//     重新生成：菜单 Yato/CodeGen/Generate Asset Keys && Pages\n" +
            "// </auto-generated>\n";

        [MenuItem("Yato/CodeGen/Generate Asset Keys && Pages", false, 301)]
        public static void GenerateAll()
        {
            string assetRoot = CodeGenSettings.AssetRoot;
            string outputFolder = CodeGenSettings.EnsureOutputFolder();

            List<string> prefabs = CollectPrefabs(assetRoot);
            if (prefabs.Count == 0)
            {
                Debug.LogWarning("[Yato.CodeGen] 未找到预制体：" + assetRoot);
                return;
            }

            int changed = 0;
            if (WriteIfChanged(Path.Combine(outputFolder, "AssetKeys.g.cs"), BuildAssetKeys(prefabs, assetRoot)))
            {
                changed++;
            }

            if (WriteIfChanged(Path.Combine(outputFolder, "UIPages.g.cs"), BuildUIPages(prefabs, assetRoot)))
            {
                changed++;
            }

            AssetDatabase.Refresh();
            Debug.Log(string.Format("[Yato.CodeGen] 完成：{0} 个预制体，写入 {1} 个文件（内容无变化则跳过）", prefabs.Count, changed));
        }

        private static List<string> CollectPrefabs(string assetRoot)
        {
            var result = new List<string>();
            if (!Directory.Exists(assetRoot))
            {
                return result;
            }

            string[] files = Directory.GetFiles(assetRoot, "*.prefab", SearchOption.AllDirectories);
            for (int i = 0; i < files.Length; i++)
            {
                string path = files[i].Replace('\\', '/');
                if (path.Contains("/Editor/") || path.Contains("~/"))
                {
                    continue;
                }

                result.Add(path);
            }

            result.Sort(StringComparer.Ordinal);
            return result;
        }

        private static string BuildAssetKeys(List<string> prefabs, string assetRoot)
        {
            var builder = new StringBuilder(2048);
            builder.Append(AutoGeneratedHeader);
            builder.Append("using Yato.Resources;\n\n");
            builder.Append("namespace Yato.Generated\n{\n");
            builder.Append("    /// <summary>资源 key 常量，避免手写字符串。</summary>\n");
            builder.Append("    public static class AssetKeys\n    {\n");

            var used = new HashSet<string>(StringComparer.Ordinal);
            for (int i = 0; i < prefabs.Count; i++)
            {
                string key = BundleNaming.GetAssetKey(prefabs[i], assetRoot);
                if (string.IsNullOrEmpty(key))
                {
                    continue;
                }

                string field = ToIdentifier(key);
                if (!used.Add(field))
                {
                    continue;
                }

                builder.Append("        public static readonly AssetKey ").Append(field)
                    .Append(" = new AssetKey(\"").Append(key).Append("\");\n");
            }

            builder.Append("    }\n}\n");
            return builder.ToString();
        }

        private static string BuildUIPages(List<string> prefabs, string assetRoot)
        {
            var builder = new StringBuilder(2048);
            builder.Append(AutoGeneratedHeader);
            builder.Append("using System;\n");
            builder.Append("using Yato.Resources;\n");
            builder.Append("using Yato.UI;\n\n");
            builder.Append("namespace Yato.Generated\n{\n");
            builder.Append("    /// <summary>页面表：页面 id → Mediator 类型 / 预制体 key / 层级。</summary>\n");
            builder.Append("    public static class UIPages\n    {\n");

            var used = new HashSet<string>(StringComparer.Ordinal);
            for (int i = 0; i < prefabs.Count; i++)
            {
                string path = prefabs[i];
                string key = BundleNaming.GetAssetKey(path, assetRoot);
                if (string.IsNullOrEmpty(key))
                {
                    continue;
                }

                string fileName = Path.GetFileNameWithoutExtension(path);
                string pageId = fileName;
                if (!used.Add(pageId))
                {
                    Debug.LogWarning("[Yato.CodeGen] 页面 id 重复，已跳过：" + pageId);
                    continue;
                }

                Type mediatorType = FindMediatorType(pageId);
                UILayer layer = GuessLayer(fileName);

                builder.Append("        public static readonly UIPageDef ").Append(ToIdentifier(pageId))
                    .Append(" = new UIPageDef(\n");
                builder.Append("            pageId: \"").Append(pageId).Append("\",\n");
                builder.Append("            mediatorType: ")
                    .Append(mediatorType != null ? "typeof(" + mediatorType.FullName + ")" : "null")
                    .Append(",\n");
                builder.Append("            prefabKey: new AssetKey(\"").Append(key).Append("\"),\n");
                builder.Append("            layer: UILayer.").Append(layer).Append(",\n");
                builder.Append("            cacheable: false,\n");
                builder.Append("            singleton: true);\n\n");
            }

            builder.Append("    }\n}\n");
            return builder.ToString();
        }

        /// <summary>按命名约定查找 Mediator（任意命名空间，类名以 Mediator 结尾）。</summary>
        private static Type FindMediatorType(string pageId)
        {
            string expected = pageId + "Mediator";
            Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
            for (int a = 0; a < assemblies.Length; a++)
            {
                Assembly assembly = assemblies[a];
                if (assembly.IsDynamic)
                {
                    continue;
                }

                Type[] types;
                try
                {
                    types = assembly.GetTypes();
                }
                catch (ReflectionTypeLoadException e)
                {
                    types = e.Types;
                }

                if (types == null)
                {
                    continue;
                }

                for (int t = 0; t < types.Length; t++)
                {
                    Type type = types[t];
                    if (type != null &&
                        type.Name == expected &&
                        typeof(UIPageMediator).IsAssignableFrom(type))
                    {
                        return type;
                    }
                }
            }

            return null;
        }

        private static UILayer GuessLayer(string pageName)
        {
            string lower = pageName.ToLowerInvariant();
            if (lower.Contains("popup") || lower.Contains("dialog") || lower.Contains("confirm"))
            {
                return UILayer.Popup;
            }

            if (lower.Contains("toast") || lower.Contains("tip"))
            {
                return UILayer.Tips;
            }

            if (lower.Contains("loading"))
            {
                return UILayer.System;
            }

            return UILayer.Normal;
        }

        private static string ToIdentifier(string key)
        {
            string[] segments = key.Split(new[] { '/', '_', '-', '.' }, StringSplitOptions.RemoveEmptyEntries);
            var builder = new StringBuilder();
            for (int i = 0; i < segments.Length; i++)
            {
                string segment = segments[i];
                builder.Append(char.ToUpperInvariant(segment[0]));
                if (segment.Length > 1)
                {
                    builder.Append(segment.Substring(1));
                }
            }

            string identifier = builder.ToString();
            if (string.IsNullOrEmpty(identifier))
            {
                identifier = "Unknown";
            }

            if (char.IsDigit(identifier[0]))
            {
                identifier = "K" + identifier;
            }

            return identifier;
        }

        /// <summary>内容相同则不写盘，避免无意义 diff。</summary>
        private static bool WriteIfChanged(string path, string content)
        {
            if (File.Exists(path))
            {
                string existing = File.ReadAllText(path);
                if (string.Equals(existing, content, StringComparison.Ordinal))
                {
                    return false;
                }
            }

            File.WriteAllText(path, content, new UTF8Encoding(false));
            return true;
        }
    }
}
